'use strict';
// Englisches Wörterbuch (v273): Schlüssel = deutscher Text wie angezeigt (Leerzeichen zusammengefasst, Zahlen als {0}, {1} …)
// Satzmuster mit Namen (v273): Namen und Teile werden über das Wörterbuch übersetzt (tr), der Satz drumherum hier
// Portionseinheiten der Grundliste (Einzahl, Mehrzahl)
const PORTION_EN = { Apfel: ['apple', 'apples'], Aubergine: ['aubergine', 'aubergines'], Banane: ['banana', 'bananas'], Becher: ['tub', 'tubs'],
  Birne: ['pear', 'pears'], Bratwurst: ['bratwurst', 'bratwursts'], Brezel: ['pretzel', 'pretzels'], 'Brötchen': ['roll', 'rolls'],
  Cheeseburger: ['cheeseburger', 'cheeseburgers'], Croissant: ['croissant', 'croissants'], Dattel: ['date', 'dates'], Dose: ['can', 'cans'],
  'Döner': ['döner', 'döners'], EL: ['tbsp', 'tbsp'], 'EL gerieben': ['tbsp grated', 'tbsp grated'], Ei: ['egg', 'eggs'], Eiklar: ['egg white', 'egg whites'],
  Falafel: ['falafel', 'falafels'], Filet: ['fillet', 'fillets'], 'Fischstäbchen': ['fish finger', 'fish fingers'], Flasche: ['bottle', 'bottles'],
  Frikadelle: ['patty', 'patties'], Glas: ['glass', 'glasses'], Gurke: ['cucumber', 'cucumbers'], Hamburger: ['hamburger', 'hamburgers'],
  Handvoll: ['handful', 'handfuls'], Karotte: ['carrot', 'carrots'], Kartoffel: ['potato', 'potatoes'], Keks: ['biscuit', 'biscuits'],
  Kiwi: ['kiwi', 'kiwis'], Knolle: ['bulb', 'bulbs'], Kohlrabi: ['kohlrabi', 'kohlrabis'], Kugel: ['scoop', 'scoops'], 'Messlöffel': ['scoop', 'scoops'],
  Orange: ['orange', 'oranges'], Packung: ['pack', 'packs'], Paprika: ['pepper', 'peppers'], Pfannkuchen: ['pancake', 'pancakes'],
  Pflaume: ['plum', 'plums'], Pizza: ['pizza', 'pizzas'], Portion: ['serving', 'servings'], Reihe: ['row', 'rows'], Reiswaffel: ['rice cake', 'rice cakes'],
  Riegel: ['bar', 'bars'], Scheibe: ['slice', 'slices'], Schenkel: ['thigh', 'thighs'], Schnitzel: ['schnitzel', 'schnitzels'], 'Schälchen': ['small bowl', 'small bowls'],
  'Schüssel': ['bowl', 'bowls'], Spiegelei: ['fried egg', 'fried eggs'], Steak: ['steak', 'steaks'], 'Stück': ['piece', 'pieces'],
  'Süßkartoffel': ['sweet potato', 'sweet potatoes'], TL: ['tsp', 'tsp'], Tasse: ['cup', 'cups'], Teller: ['plate', 'plates'], Tomate: ['tomato', 'tomatoes'],
  Viertel: ['quarter', 'quarters'], Wrap: ['wrap', 'wraps'], 'Würstchen': ['sausage', 'sausages'], Zucchini: ['courgette', 'courgettes'],
  Zwiebel: ['onion', 'onions'], Oliven: ['olive', 'olives'] };
const RX_LEVEL = { Fan: 'fan', Profi: 'pro', Meister: 'master', Legende: 'legend', Ikone: 'icon' };
I18N_RX.en.push(
  // v317: Startseite nach dem neuen Plan
  [/^Als Erstes steht (.+) an\. Die App führt dich Satz für Satz durch das Training\.$/, m => `First up is ${tr(m[1])}. The app guides you through the workout set by set.`],
  [/^Neuer Erfolg: (.+)$/, m => `New achievement: ${tr(m[1])}`],
  // v306: Assistent-Vorschau „⭐ Priorität: Brust, Lat“ / „😌 Low: Bauch“
  [/^⭐ Priorität: (.+)$/, m => `⭐ Priority: ${m[1].split(', ').map(tr).join(', ')}`],
  [/^😌 Low: (.+)$/, m => `😌 Low: ${m[1].split(', ').map(tr).join(', ')}`],
  // v306: Ø Tank im Training („(Ziel mind. 3), schwerer als geplant“)
  [/^\(Ziel (mind\. )?(.+?)\), (✔ im Ziel|leichter als geplant|schwerer als geplant)$/, m =>
    `(target ${m[1] ? 'at least ' : ''}${m[2]}), ${{ '✔ im Ziel': '✔ on target', 'leichter als geplant': 'easier than planned', 'schwerer als geplant': 'harder than planned' }[m[3]]}`],
  [/^Neue Bestleistung bei (.+?) und (\d+) weiteren Übungen?\. Richtig gut\.$/, m => `New personal best in ${tr(m[1])} and ${m[2]} more exercise${m[2] === '1' ? '' : 's'}. Really good.`],
  [/^Neue Bestleistung bei (.+?)\. Richtig gut\.$/, m => `New personal best in ${tr(m[1])}. Really good.`],
  [/^(\d+) Trainings mit (.+)$/, m => `${m[1]} workouts with ${tr(m[2])}`],
  [/^Erstmals ([\d.,]+) (kg|lb) bei (.+)$/, m => `First time ${m[1]} ${m[2]} in ${tr(m[3])}`],
  [/^(.+)-(Fan|Profi|Meister|Legende|Ikone)$/, m => { const n = tr(m[1]); return n === m[1] ? null : `${n} ${RX_LEVEL[m[2]]}`; }],
  [/^(.+): \+?([\d.,]+) (kg|lb|%)$/, m => { const n = tr(m[1]); return n === m[1] ? null : `${n}: ${m[0].slice(m[1].length + 2)}`; }],
  // v303: Scheiben-Marken (lb)
  [/^(.+): (Eine|Zwei|Drei|Vier|Fünf) Scheiben?$/, m => `${tr(m[1])}: ${{ Eine: 'One', Zwei: 'Two', Drei: 'Three', Vier: 'Four', Fünf: 'Five' }[m[2]]} plate${m[2] === 'Eine' ? '' : 's'}`],
  [/^([\d.,]+) lb bei (.+) \((\d) × 45 lb je Seite\)$/, m => `${m[1]} lb in ${tr(m[2])} (${m[3]} × 45 lb per side)`],
  [/^Geplant waren für „(.+)“ ca\. (.+?), gebraucht hast du (.+)\.$/, m => `Planned for “${tr(m[1])}” was approx. ${m[2]}, you needed ${m[3]}.`],
  [/^🔄 (\d+) von (\d+) Trainings erledigt \| offen: (.+)$/, m => `🔄 ${m[1]} of ${m[2]} workouts done | open: ${m[3].split(', ').map(tr).join(', ')}`],
  [/^(\d+)\. (.+)$/, m => { const n = tr(m[2]); return n === m[2] ? null : `${m[1]}. ${n}`; }],
  [/^Stillstand bei (.+)$/, m => `Plateau in ${tr(m[1])}`],
  [/^💬 Letztes Mal: „(.*)“$/s, m => `💬 Last time: “${m[1]}”`],
  [/^→ (\d+) lässt sich nicht gleichmäßig auf ([\d.,]+) Trainings verteilen, es werden (\d+)\. (.+)$/, m =>
    `→ ${m[1]} can't be spread evenly over ${m[2]} workouts, it will be ${m[3]}. ${tr(m[4])}`],
  [/^(.*?)(?: \| )?⚠ tatsächlich: ((?:\d+ \| )*\d+) \((.+)\)$/, m =>
    `${m[1] ? tr(m[1]) + ' | ' : ''}⚠ actual: ${m[2]} (${m[3].split('; ').map(tr).join('; ')})`],
  // Ernährungstagebuch: leere Mahlzeiten (Liste mit „und“), offene Tage
  [/^(Eingetragen: [\d.,]+ kcal\. |⚠️ )?(.+?) (ist|sind) leer, sonst trägst du (?:es|sie) fast immer ein\.(.*)$/, m => {
    const meals = m[2].split(' und ').map((x, i) => { const t = tr(x); return i ? t.toLowerCase() : t; }).join(' and ');
    const head = m[1] ? (m[1].startsWith('⚠️') ? '⚠️ ' : `Logged: ${m[1].slice(13, -7)} kcal. `) : '';
    return `${head}${meals} ${m[3] === 'ist' ? 'is' : 'are'} empty, otherwise you almost always log ${m[3] === 'ist' ? 'it' : 'them'}.${m[4] ? ' ' + tr(m[4].trim()) : ''}`;
  }],
  [/^Erst abgeschlossene Tage zählen für den gemessenen Bedarf\.(?: Noch (\d+) (?:weiterer Tag|weitere Tage) offen\.)?$/, m =>
    `Only finished days count towards your measured requirement.${m[1] ? ` ${m[1]} more day${m[1] === '1' ? '' : 's'} still open.` : ''}`],
  // Beschwerden: Stelle (mit Seite) und „seit“
  [/^(.+) (links|rechts|beidseits)$/, m => { const a = tr(m[1]); return a === m[1] ? null : `${a} (${{ links: 'left', rechts: 'right', beidseits: 'both sides' }[m[2]]})`; }],
  // Ernährungsziel: „Tempo | seit Datum | Woche …“ (v315)
  [/^([^|]+) \| seit ([^|]+) \| (.+)$/, m => `${tr(m[1])} | since ${m[2]} | ${tr(m[3])}`],
  [/^(.+?) seit (.+)$/, m => { const a = tr(m[1]); return a === m[1] ? null : `${a} since ${m[2].split(' | ').map(tr).join(' | ')}`; }],
  [/^Seit (.+?)(?: \| (.+))?$/, m => `Since ${m[1]}${m[2] ? ' | ' + tr(m[2]) : ''}`],
  [/^Zuletzt angegeben am (.+?)(?: \| (.+))?$/, m => `Last reported on ${m[1]}${m[2] ? ' | ' + tr(m[2]) : ''}`],
  [/^Bild deines Trainings (.+)$/, m => `Image of your workout ${tr(m[1])}`],
  // Ernährung: Vorschlag zur Aktivität, „… für „Tempo/Stufe““
  [/^Vorschlag aus deinen Daten(?: \((.+)\))?: <b>(.+)<\/b>\.$/, m =>
    `Suggestion from your data${m[1] ? ` (${m[1].split(' und ').map(tr).join(' and ')})` : ''}: <b>${tr(m[2])}</b>.`],
  [/^(.*?) ?für „([^“]+)“(\.?)$/, m => {
    const a = !m[1] ? '' : i18nWord(m[1]) ? i18nLookup(m[1]) : m[1];
    return a == null ? null : `${a}${a ? ' ' : ''}for “${tr(m[2])}”${m[3]}`;
  }],
  // Plan-Assistent: empfohlene Trainings je Erfahrungsstufe
  [/^Danach schlägt dir die App passende Pläne vor\. Als (.+?) sind <b>(.+?)<\/b> ideal \(markiert\)\. Wähle lieber eine Zahl, die du auch auf Dauer schaffst\.$/, m => {
    const lvl = tr(m[1]).toLowerCase();
    return `The app then suggests suitable plans. As ${/^[aeiou]/.test(lvl) ? 'an' : 'a'} ${lvl}, <b>${tr(m[2])}</b> are ideal (marked). Rather choose a number you can keep up in the long run.`;
  }],
  // v367: Planwechsel (Toast)
  [/^„(.+)“ ist (jetzt|wieder) aktiv$/, m => `“${m[1]}” is ${m[2] === 'jetzt' ? 'now' : 'active again'} active`.replace('active again active', 'active again')],
  // v365: aufgeklappte Zykluskarte – Erklärung + „Eine Woche ist geschafft, sobald …“ (vorher nie übersetzt)
  [/^(.+?) Eine Woche ist geschafft, sobald (.+?), egal, wie viele Tage du dafür brauchst\.$/, m => {
    const a = i18nLookup(m[1]), b = i18nLookup(m[2]);
    return a == null || b == null ? null : `${a} A week is done as soon as ${b}, no matter how many days it takes.`;
  }],
  // v365: Erholungspause (Pause statt Deload) – Texte mit Datum
  [/^Weiter geht es ab (.+?)(?:, gern auch erst am (.+?))?, mit der Intro-Woche des nächsten Zyklus\.\s*(?:<small>Noch (\d+) (?:Tag|Tage) Pause<\/small>)?$/, m =>
    `You can continue from ${m[1]}${m[2] ? `, or wait until ${m[2]}` : ''}, with the intro week of the next cycle.${m[3] ? ` <small>${m[3]} ${m[3] === '1' ? 'day' : 'days'} of rest left</small>` : ''}`],
  [/^Deine Erholungspause läuft noch\. Am besten trainierst du erst wieder ab (.+)\.\n\nTrotzdem jetzt mit der Intro-Woche starten\?$/, m =>
    `Your rest break is still running. Ideally, train again from ${m[1]}.\n\nStart the intro week now anyway?`],
  // v360: Beschriftungen in der Übungsvorschau des Assistenten
  [/^Intensitätstechnik für (.+)$/, m => `Intensity technique for ${tr(m[1])}`],
  // v368: Sätze mit Übungs-, Plan- und Muskelnamen (Name in „…“ wird für sich übersetzt)
  [/^⚠️ Mit dieser Ausrüstung gibt es keine Übung für: <b>(.+)<\/b>\. Schon ein Widerstandsband hilft\.$/, m =>
    `⚠️ With this equipment there is no exercise for: <b>${m[1].split(', ').map(x => tr(x)).join(', ')}</b>. Even a resistance band helps.`],
  [/^<b>Beschwerden in diesem Zyklus:<\/b> (.+)\. Betroffene Übungen sind im Training markiert\. Bei Schmerzen den Satz abbrechen\.$/, m => {
    const side = { links: 'left', rechts: 'right', beidseits: 'both sides' };
    const item = x => { const p = x.match(/^(.+?)( \(\d+\/10\))?$/); let n = p[1]; const w = n.split(' '), last = w[w.length - 1];
      n = side[last] ? `${tr(w.slice(0, -1).join(' '))} ${side[last]}` : tr(n); return n + (p[2] || ''); };
    return `<b>Complaints this cycle:</b> ${m[1].split(', ').map(item).join(', ')}. Affected exercises are marked in training. Stop the set if it hurts.`;
  }],
  [/^„(.+)“ ersetzen$/, m => `Replace “${tr(m[1])}”`],
  [/^(.+) ersetzen$/, m => `Replace ${tr(m[1])}`],
  [/^„(.+)“ umbenennen$/, m => `Rename “${tr(m[1])}”`],
  [/^„(.+)“ im Wechsel mit …$/, m => `“${tr(m[1])}” alternating with …`],
  [/^„(.+)“ aus dem Plan entfernen\?$/, m => `Remove “${tr(m[1])}” from the plan?`],
  [/^„(.+)“ entfernen\? Übungen dieser Muskelgruppe bekommen ihre Sätze dann wieder von Hand\.$/, m => `Remove “${tr(m[1])}”? Exercises of this muscle group then get their sets by hand again.`],
  [/^⚠️ (.+) ist eine Grundübung\. Hier leidet bei einem (Reduktionssatz|Myo-Satz) schnell die Technik\. Besser bei Maschinen-, Kabel- oder Isolationsübungen einsetzen\.$/,
    m => `⚠️ ${tr(m[1])} is a compound lift. With a ${m[2] === 'Myo-Satz' ? 'myo set' : 'drop set'} technique quickly suffers here. Better use it on machine, cable or isolation exercises.`],
  [/^Deine Kraft bei (.+) ist (\d+) % über deinem Start$/, m => `Your strength in ${tr(m[1])} is ${m[2]} % above your start`],
  [/^Plan „(.+)“ mit (\d+) Trainingstag(?:en)? löschen\?$/, m => `Delete plan “${m[1]}” with ${m[2]} training day${m[2] === '1' ? '' : 's'}?`],
  [/^Plan „(.+)“ beenden\?$/, m => `End plan “${m[1]}”?`],
  [/^„(.+)“ beendet$/, m => `“${m[1]}” ended`],
  [/^erstes Training mit „(.+)“$/, m => `first workout with “${m[1]}”`],
  [/^„(.+)“ gespeichert, beim Hinzufügen ganz oben$/, m => `“${m[1]}” saved, shown at the top when adding`],
  [/^(.+) hinzugefügt ✔$/, m => `${tr(m[1])} added ✔`],
  [/^(Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember): (\d+) Trainings?$/, m =>
    `${['January','February','March','April','May','June','July','August','September','October','November','December'][['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'].indexOf(m[1])]}: ${m[2]} workout${m[2] === '1' ? '' : 's'}`],
  [/^„([^„“]+)“$/, m => { const t = i18nLookup(m[1]); return t == null ? null : `“${t}”`; }],
  // v360: Zeit-Pfad, gleiche Empfehlung mit anderem ersten Satz
  [/^Bei mehr Tagen pro Woche werden die einzelnen Trainings kürzer\. Als (.+?) sind <b>(.+?)<\/b> ideal \(markiert\)\. Wähle lieber eine Zahl, die du auch auf Dauer schaffst\.$/, m => {
    const lvl = tr(m[1]).toLowerCase();
    return `With more days per week, each workout gets shorter. As ${/^[aeiou]/.test(lvl) ? 'an' : 'a'} ${lvl}, <b>${tr(m[2])}</b> are ideal (marked). Rather choose a number you can keep up in the long run.`;
  }],
  // Motivation (Startseite, nach dem Training)
  [/^Schön, dass du da bist\. Als Nächstes wartet <b>(.+)<\/b>, wann immer es dir passt\.$/, m => `Good to see you. Next up is <b>${tr(m[1])}</b>, whenever it suits you.`],
  [/^(\d+) Tage ohne Training\. <b>(.+)<\/b> wartet\. Heute ist ein guter Tag dafür\.$/, m => `${m[1]} days without training. <b>${tr(m[2])}</b> is waiting. Today is a good day for it.`],
  [/^Neue Bestleistung bei (.+?)(?: und (\d+) weiteren Übungen?)?\. Du siehst: Die harte Arbeit zahlt sich aus\.$/, m =>
    `New personal best in ${tr(m[1])}${m[2] ? ` and ${m[2]} more exercise${m[2] === '1' ? '' : 's'}` : ''}. You see: the hard work pays off.`],
  [/^(.+?)\. Betroffene Übungen sind im Training markiert\. Bei Schmerzen den Satz abbrechen\.$/, m =>
    `${m[1].split(', ').map(x => x.replace(/^(.+?)( \(\d+\/10\))?$/, (_, a, b) => tr(a) + (b || ''))).join(', ')}. Affected exercises are marked during the workout. Stop the set if it hurts.`],
  // Plan-Assistent: Supersatz-Hinweis in der Vorschau, fertig angelegter Plan
  [/^in Wochen, in denen (.+) mehr Sätze hat, beginnst du damit$/, m => `in weeks where ${tr(m[1])} has more sets, you start with it`],
  [/^„(.+)“ erstellt und aktiv ✔$/, m => `“${m[1]}” created and active ✔`],
  // Übungsbibliothek: Zielmuskel und Mitbeteiligte (Listen mit Komma)
  [/^(?:<b>Zielmuskel:<\/b> (.+?))?(?:(?:^| \| )<b>mit dabei:<\/b> (.+))?$/, m => {
    if (!m[1] && !m[2]) return null;
    const list = x => x.split(', ').map(tr).join(', ');
    return [m[1] && `<b>Target muscle:</b> ${list(m[1])}`, m[2] && `<b>Also involved:</b> ${list(m[2])}`].filter(Boolean).join(' | ');
  }],
  // Hyrox-Uhr, Calisthenics-Ziele, Verlauf und betroffene Übungen
  [/^(.+) fertig ✓$/, m => `${tr(m[1])} done ✓`],
  [/^▶ (.+) starten$/, m => `▶ Start ${tr(m[1])}`],
  [/^Als Nächstes: (.+)$/, m => `Next: ${tr(m[1])}`],
  [/^(?:(\d+)\. )?(.+) \(Ziel (\d+)(?: × (\d+))?( s)?( sauber)?( je Seite)?\)$/, m => {
    const n = tr(m[2]); if (n === m[2] && /[äöüß]/.test(n)) return null;
    return `${m[1] ? m[1] + '. ' : ''}${n} (goal ${m[3]}${m[4] ? ' × ' + m[4] : ''}${m[5] || ''}${m[6] ? ' clean' : ''}${m[7] ? ' per side' : ''})`;
  }],
  [/^Verlauf (.+)$/, m => { const n = tr(m[1]); return n === m[1] ? null : `${n} history`; }],
  [/^Betrifft im Plan: (.+)$/, m => `Affects in the plan: ${m[1].split(', ').map(tr).join(', ')}`],
  [/^Strecken, Gewichte für (.+), Ausführung$/, m => `Distances, weights for ${tr(m[1])}, execution`],
  [/^Ziel: (\d+)(?: × (\d+))?( s)?( sauber)?( je Seite)?$/, m => `Goal: ${m[1]}${m[2] ? ' × ' + m[2] : ''}${m[3] || ''}${m[4] ? ' clean' : ''}${m[5] ? ' per side' : ''}`],
  // Portionen der Grundliste: „1 Becher (150 g)“, „1 Ei (M)“, „5 Oliven“
  [/^(\d+) ([^()]+?)( \((?:geschält|roh|trocken|abgetropft|M|[\d.,]+ (?:ml|l))\))?(?: \(([\d.,]+) (g|oz)\))?$/, m => {
    const u = PORTION_EN[m[2]]; if (!u) return null;
    const q = { geschält: 'peeled', roh: 'raw', trocken: 'dry', abgetropft: 'drained', M: 'M' };
    const x = m[3] ? ' (' + m[3].slice(2, -1).replace(/^(geschält|roh|trocken|abgetropft|M)$/, k => q[k]).replace(/(\d),(\d)/, '$1.$2') + ')' : '';
    return `${m[1]} ${m[1] === '1' ? u[0] : u[1]}${x}${m[4] ? ` (${m[4]} ${m[5]})` : ''}`;
  }],
  [/^Tagesform: (.+)$/, m => `Daily form: ${m[1].split(', ').map(tr).join(', ')}`],
  // v355: Mobility
  [/^Antippen ＋ fügt die Übung zu „(.+)“ hinzu\. Der Pfeil zeigt, wie sie geht und wofür sie gut ist\.$/, m => `Tap ＋ to add the exercise to “${tr(m[1])}”. The arrow shows how it works and what it is good for.`],
  [/^„(.+)“ aus der Mobility dieses Tages entfernen\?$/, m => `Remove “${tr(m[1])}” from this day's mobility?`],
  [/^🤸 Mobility: (.+)$/, m => `🤸 Mobility: ${m[1].split(', ').map(tr).join(', ')}`],
  // v353: „Wenig Zeit?“: gekürzte und weggelassene Übungen, Supersätze von heute
  [/^Weniger Sätze: (.+)$/, m => `Fewer sets: ${m[1].split(' | ').map(p => p.replace(/^(.+) (\d+) → (\d+)$/, (_, n, a, b) => `${tr(n)} ${a} → ${b}`)).join(' | ')}`],
  [/^Heute ausgelassen: (.+)$/, m => `Skipped today: ${m[1].split(' | ').map(tr).join(' | ')}`],
  [/^🔗 Heute im Supersatz: (.+)$/, m => `🔗 Superset today: ${m[1].split(' | ').map(p => p.split(' + ').map(tr).join(' + ')).join(' | ')}`],
  // v352: dazu der Satz zur reinen Trainingszeit (im Gym etwa 15 Minuten mehr); Assistent: Intro → Woche 4
  [/^⏱ So lange dauern deine Training(?:stage|s) damit etwa \(Intro → (Höhepunkt|Woche 4)\): (.+?)\.(?: Das ist die reine Trainingszeit, im Gym kommen etwa (\d+) Minuten dazu\.)?( Das ist etwas länger.*)?$/s, m =>
    `⏱ That's roughly how long your training days take (intro → ${m[1] === 'Höhepunkt' ? 'peak' : 'week 4'}): ${
    m[2].split(' | ').map(p => p.replace(/^<b>(.+?)<\/b> ca\. /, (_, n) => `<b>${tr(n)}</b> approx. `)).join(' | ')}.${m[3] ? ` That is pure training time, at the gym add about ${m[3]} minutes.` : ''}${m[4] ? ' ' + tr(m[4].trim()) : ''}`],
  // Nahrungsergänzung (v279)
  [/^„(.+)“ aus deinen Präparaten löschen\?(\s*)Bereits eingetragene Tage bleiben erhalten\.$/s, m => `Delete “${m[1]}” from your supplements?${m[2]}Days already logged are kept.`],
  [/^„(.+)“ aus deinen Präparaten löschen\?$/, m => `Delete “${m[1]}” from your supplements?`],
  [/^„(.+)“ ist in Open Food Facts ohne Nährstoffangaben je Portion\. Bitte die Werte von der Packung abtragen\.$/, m =>
    `“${m[1] === 'Das Präparat' ? 'The supplement' : m[1]}” is in Open Food Facts without nutrient data per serving. Please copy the values from the package.`],
  [/^Bitte bei „(.+)“ eine Zahl eintragen\.$/, m => `Please enter a number for “${tr(m[1])}”.`],
  [/^Aus „(.+)“ entfernen$/, m => `Remove from “${tr(m[1])}”`],
  [/^Aus (.+) entfernen$/, m => { const n = tr(m[1]); return n === m[1] ? null : `Remove from ${n.toLowerCase()}`; }],
  [/^„(.+)“ entfernen\?$/, m => `Remove “${tr(m[1])}”?`],
  [/^„(.+)“ für dieses Training weglassen\?(\s*)(Die eingetragenen Sätze dieser Übung gehen verloren\. )?Im Plan bleibt die Übung, beim nächsten Mal ist sie wieder dabei\.$/s, m =>
    `Skip “${tr(m[1])}” for this workout?${m[2]}${m[3] ? 'The sets you entered for this exercise will be lost. ' : ''}It stays in the plan and will be back next time.`],
  [/^„(.+)“ heute weggelassen$/, m => `“${tr(m[1])}” skipped today`],
  [/^🔗 Supersatz nur für heute: (.+) \+ (.+)$/, m => `🔗 Superset for today only: ${tr(m[1])} + ${tr(m[2])}`],
  [/^🔗 Supersatz dauerhaft im Plan: (.+) \+ (.+)$/, m => `🔗 Superset saved in the plan: ${tr(m[1])} + ${tr(m[2])}`],
  [/^„(.+)“ für dieses Training weglassen\?$/, m => `Skip “${tr(m[1])}” for this workout?`],
  [/^📝 (\d+) Tage? ohne Eintrag \((.+)\)$/, m => `📝 ${m[1]} day${m[1] === '1' ? '' : 's'} without entry (${m[2].replace(' bis ', ' to ')})`],
  [/^Hier passt du die Übung an: (.+)\. Die App merkt sich, ob du den Bereich lieber offen oder zu hast\.$/, m =>
    `Here you adjust the exercise: ${m[1].split(/, | und /).map(x => { const t = tr(x); return t === x ? x : t.charAt(0).toLowerCase() + t.slice(1); }).join(', ').replace(/, ([^,]+)$/, ' and $1')}. The app remembers whether you prefer this section open or closed.`],
  [/^(.+) wie geplant eingetragen ✔$/, m => `${tr(m[1])} logged as planned ✔`],
  // v338: Ernährungsplan (Ersatz-Zutat, Packungen in der Einkaufsliste)
  [/^statt (.+)$/, m => `instead of ${tr(m[1])}`],
  // v339: Alternative zurücksetzen („↺ Zutat“)
  [/^↺ (.+)$/, m => `↺ ${tr(m[1])}`],
  // v344: Yoga
  // v345: Vergleich mit dem letzten Mal
  [/^Noch keine Einheit (.+)\. Ab dem nächsten Mal siehst du hier den Vergleich\.$/, m => `No ${tr(m[1])} session yet. From next time you'll see the comparison here.`],
  [/^(\S+) Erste Einheit (.+)$/, m => `${m[1]} First ${tr(m[2])} session`],
  [/^(\S+) Vergleich mit dem letzten Mal$/, m => `${m[1]} Compared with last time`],
  [/^Tempo in (.+), oben = schneller, letzte (\d+) Einheiten mit Strecke$/, m => `Pace in ${m[1]}, higher = faster, last ${m[2]} sessions with distance`],
  [/^Zuletzt (.+)$/, m => `Last ${m[1].replace(/Runden/, 'rounds').replace('ohne Angaben', 'without details')}`],
  [/^🧘 (.+)$/, m => `🧘 ${tr(m[1])}`],
  [/^zuletzt (.+)$/, m => `last ${m[1]}`],
  // v341: „Was hab ich da?“
  [/^([\d.,]+) kcal für (.+) heute$/, m => `${m[1].replace(/\./g, ',')} kcal for ${tr(m[2])} today`],
  [/^Für (.+) heute eingeplant ✔$/, m => `Planned for ${tr(m[1])} today ✔`],
  [/^(.+) eingetragen ✔$/, m => `${tr(m[1])} logged ✔`],
  [/^≈ (\d+) (Dose|Dosen|Becher|Packung|Packungen)$/, m => `≈ ${m[1]} ${{ Dose: 'can', Becher: 'tub', Packung: 'pack' }[m[2].replace(/n$/, '').replace('Packunge', 'Packung')] || 'pack'}${m[1] === '1' ? '' : 's'}`],
);

